@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
  + address : string
}

class ScientificArticle {
  + DOI : string
  + title : string
  + authors : Person[]
  + positionOfAuthor : int[]
}

interface PeerReviewedPaper {}
interface TechnicalReport {}

ScientificArticle "1" --|> PeerReviewedPaper
ScientificArticle "1" --|> TechnicalReport

class Publisher {
  + name : string
}

Publisher *-- "0..*" Journal

class Journal {
  + publisherName : string
  + journalName : string
  + impactFactor : float
}

PeerReviewedPaper "1" -- "0..1" Journal

Person "1" -- "0..*" ScientificArticle : isAuthorOf
Person "1" -- "0..*" ScientificArticle : isReviewerOf

ResearchInstitution "1" -- "0..*" TechnicalReport : publishes

@enduml

